    end

    if _G.HousingMgr:IsInDoor() then
        self.PreviewModelData.InternalDepot[DepotData.Type] = Items
    else
        self.PreviewModelData.HouseDepot[DepotData.Type] = Items
    end
end

function HouseMainPanelVM:AddInternalData(Items)
