    end

    self.PreviewModelData.ExteriorData = LocalItems
end

function HouseMainPanelVM:ReplacePreviewItem(From)
    local FromType = nil
    local FromSubType = nil
    local ToType = nil
    local ToSubType = nil
    local To = nil

    local HousingMgr = _G.HousingMgr

    if HousingMgr:IsInDoor() then
        if self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Bag then
            FromType = HouseCommon.PreviewModelDataType.Bag
        else
            FromType = HouseCommon.PreviewModelDataType.InternalDepot
        end

        local PartsCategory = self:RevertPartsCategoryToHouseItemCategory(HousingMgr.SelectInDoorPartsCategory,true)

        FromSubType = PartsCategory
        ToType = HouseCommon.PreviewModelDataType.InternalData
        ToSubType = FromSubType
    else
        if self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Bag then
            FromType = HouseCommon.PreviewModelDataType.Bag
        else
            FromType = HouseCommon.PreviewModelDataType.HouseDepot
        end

        local PartsCategory = self:RevertPartsCategoryToHouseItemCategory(HousingMgr.SelectHousePartsCategory,false)

        FromSubType = PartsCategory
        ToType = HouseCommon.PreviewModelDataType.ExteriorData
        ToSubType = FromSubType
    end


    local FromTypeItemList = {}
    local ToTypeItemList = {}

    if FromType == HouseCommon.PreviewModelDataType.Bag then
        FromTypeItemList = self.PreviewModelData.Bag[FromSubType]
    elseif FromType == HouseCommon.PreviewModelDataType.InternalDepot then
        FromTypeItemList = self.PreviewModelData.InternalDepot[FromSubType]
    elseif FromType == HouseCommon.PreviewModelDataType.HouseDepot then
        FromTypeItemList = self.PreviewModelData.HouseDepot[FromSubType]
    end

    if ToType == HouseCommon.PreviewModelDataType.InternalData then
        ToTypeItemList = self.PreviewModelData.InternalData
    elseif ToType == HouseCommon.PreviewModelDataType.ExteriorData then
        ToTypeItemList = self.PreviewModelData.ExteriorData
    end

    local SlotIndex = HouseUtil.GetSlotIndexWithPartsCategory(HousingMgr.SelectInDoorPartsCategory)

    --室内根据层数和当前选择的位置算具体那个位置
    if HousingMgr:IsInDoor() then
        if HousingMgr.SelectFloor == HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON then
            SlotIndex = 10
        else
            SlotIndex = HousingMgr.SelectFloor * 3 - 2 + SlotIndex - 1
        end
        To = ToTypeItemList[SlotIndex]
    else
        SlotIndex = HouseUtil.GetSlotIndexWithHousePartsCategory(HousingMgr.SelectHousePartsCategory)
        To = ToTypeItemList[SlotIndex]

        if To.GID == 0 then
            To = nil
        end
    end

    --如果To为nil说明那个slot是空的，所以要先把右方背包或者仓库的ITEM删除再替换掉下方的装修Slot
    if To == nil then
        self:RemovePreviewItem(FromType,FromSubType,From)
        self:AddPreviewItem(ToType,ToSubType,From,SlotIndex)
        --更新右边道具栏
        self:UpdateItemList()
        --更新下面的装修slot
        _G.EventMgr:SendEvent(_G.EventID.UpdateDecorateSlotItem,{Item = From,Index = SlotIndex})
    else
        local FromItem = {GID = From.GID,ResID = From.ResID}
        if FromTypeItemList ~= nil then
            for k,v in pairs(FromTypeItemList) do
                if v.GID == From.GID and v.ResID == From.ResID then
                    v.GID = To.GID
                    v.ResID = To.ResID
                    break
                end
            end

            --更新右边道具栏
            self.ItemIndex = self:UpdateItemIndexByGID(From.GID)

            local CurItemVM = self.CurrentItemVMList:Get(self.ItemIndex)

            if CurItemVM ~= nil then
                CurItemVM:UpdateVM({Index = CurItemVM.Index,GID = To.GID,ResID = To.ResID})
            end

        else
            FLOG_INFO("Replace From ItemList Empty")
        end

        for k,v in pairs(ToTypeItemList) do
            if v.GID == To.GID and v.ResID == To.ResID then
                v.GID = FromItem.GID
                v.ResID = FromItem.ResID
                --更新下面的装修slot
                _G.EventMgr:SendEvent(_G.EventID.UpdateDecorateSlotItem,{Item = FromItem,Index = SlotIndex})
                break
            end
        end
    end
end

function HouseMainPanelVM:RemovePreviewItem(Type,SubType,Item,Index)
    local ItemList = {}
    if Type == HouseCommon.PreviewModelDataType.Bag then
        ItemList = self.PreviewModelData.Bag[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.InternalDepot then
        ItemList = self.PreviewModelData.InternalDepot[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.HouseDepot then
        ItemList = self.PreviewModelData.HouseDepot[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.InternalData then
        ItemList = self.PreviewModelData.InternalData
    elseif Type == HouseCommon.PreviewModelDataType.ExteriorData then
        ItemList = self.PreviewModelData.ExteriorData
    end

    --只有外装的可选配件才会有
    if Index ~= nil then
        if ItemList[Index] ~= nil then
            ItemList[Index].GID = 0
        end
    else
        if ItemList ~= nil then
            Index = 1
            for k,v in ipairs(ItemList) do
                if v.GID == Item.GID and v.ResID == Item.ResID then
                    table.remove(ItemList,Index)
                    return
                end
                Index = Index + 1
            end
        end
    end
end

function HouseMainPanelVM:AddPreviewItem(Type,SubType,Item,Index)
    local ItemList = {}

    if Type == HouseCommon.PreviewModelDataType.Bag then
        ItemList = self.PreviewModelData.Bag[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.InternalDepot then
        ItemList = self.PreviewModelData.InternalDepot[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.HouseDepot then
        ItemList = self.PreviewModelData.HouseDepot[SubType]
    elseif Type == HouseCommon.PreviewModelDataType.InternalData then
        ItemList = self.PreviewModelData.InternalData
    elseif Type == HouseCommon.PreviewModelDataType.ExteriorData then
        ItemList = self.PreviewModelData.ExteriorData
    end

    --这里说明蛤要将当前Itemlist中Index位置的ITEM的GID,RESID都置Item中的值
    if Index ~= nil then
        if ItemList~= nil and ItemList[Index] ~= nil then
            ItemList[Index].GID = Item.GID
            ItemList[Index].ResID = Item.ResID
        end
    else
        table.insert(ItemList,{GID = Item.GID,ResID = Item.ResID})
    end
end

--判断当前ITEM是不是被交换了，比如背包中的道具替换成了内外装SLOT中的道具这是在预览模式下
function HouseMainPanelVM:IsItemIsReplaced(Item,Slot)
    --查找原始数据确定有没有被变动
    if Slot == HouseCommon.SelectHouseLeftBarType.Bag then
        if _G.BagMgr:FindItem(Item.GID) ~= nil then
            return false
        end
    elseif Slot == HouseCommon.SelectHouseLeftBarType.StoreHouse then
        if _G.HousingMgr:FindDepotItem(Item.GID) then
            return false
        end
    elseif Slot == HouseCommon.SelectHouseLeftBarType.DecorateSlot then
        --只有外装才会需要判断替换(可选配件可为空所以可以收回到背包，在收回前需要判断是否已替换成其它物件了)
        local DoUpData = _G.HousingMgr:GetCurHouseDecorateData()

        if DoUpData.Floors ~= nil and #DoUpData.Floors > 0 then
            for k, Entity in pairs(DoUpData.Floors[1].Entities) do
                if Entity.GID == Item.GID then
                    return false
                end
            end
        end
        if DoUpData.Global ~= nil and #DoUpData.Global > 0 then
            for k, Entity in pairs(DoUpData.Global[1].Entities) do
                if Entity.GID == Item.GID then
                    return false
                end
            end
        end
    end

    return true
end

