--region 菜单列表
function HouseMainPanelVM:GetDefaultMenuKey()
    if nil == self.TabList then
        return 0
    end

    for k,v in pairs(self.TabList) do
        if v.Key == self.TabSelectIndex then
            if nil ~= v.Children and next(v.Children) then
                return v.Children[1].Key
            else
                return v.Key
            end
        end
    end

    return 0
end

function HouseMainPanelVM:UpdateItemList()
    self.CurrentItemVMList:Clear()
    local ItemTypes = {}
    local HouseItems = {}

    local SelectGID = 0

    --先记一下之前选的GID
    --[[
    for i = 1, self.CurrentItemVMList:Length() do
        local ItemVM = self.CurrentItemVMList:Get(i)
        if ItemVM.IsSelect then
            SelectGID = ItemVM.GID
            break
        end
    end--]]

    if _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.FurnitureModel or _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.YardModel then
        self:UpdatePlacedInfo()
    end

    --已放置
    if self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Placed then
        self:UpdateDepotInfo()
        local HouseDecorateInfo = _G.HousingMgr:GetHouseInfo(_G.HousingMgr.HouseID,_G.HousingMgr.Region)

        if HouseDecorateInfo ~= nil and HouseDecorateInfo.Furniture ~= nil then
            local RefreshData = {}
            
            if _G.HousingMgr:IsInDoor() then
                for _,Entity in pairs(HouseDecorateInfo.Furniture.Entities) do
                    local Cfg = HousingFurnitureCfg:FindCfgByKey(Entity.Key)

                    if self.TabSelectType == 100 or self.TabSelectType == 101 or self.TabSelectType == 102 then
                        table.insert(HouseItems,{GID = Entity.GID,ResID = Cfg.ItemID})
                    else
                        if Cfg.Category == HouseCommon.HousingItemCategoryMap[self.TabSelectType] then
                            table.insert(HouseItems,{GID = Entity.GID,ResID = Cfg.ItemID})
                        end
                    end
                end
            else
                for _,Entity in pairs(HouseDecorateInfo.Furniture.Entities) do
                    local Cfg = HousingYardCfg:FindCfgByKey(Entity.Key)
                    table.insert(HouseItems,{GID = Entity.GID,ResID = Cfg.ItemID})
                end
            end

            for k,Item in pairs(HouseItems) do
                Item.Index = #RefreshData + 1

                --if Item.GID == SelectGID then
                    --Item.Selected = true
                --end

                RefreshData[#RefreshData + 1] = Item
            end

            if #RefreshData > 0 then
                self.CommBackpackEmptyVisible = false
                self.CommBackpackEmptySVisible = false
                self.CurrentItemVMList.UpdateVMParams = {IsAllowDoubleClick = true}
                self.CurrentItemVMList:UpdateByValues(RefreshData)
            else
                if _G.HousingMgr:GetRightBarExpend() then
                    self.CommBackpackEmptyVisible = true
                    self.CommBackpackEmptySVisible = false
                else
                    self.CommBackpackEmptyVisible = false
                    self.CommBackpackEmptySVisible = true
                end
            end
        end

    elseif self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Bag or self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.StoreHouse then
        if _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.IndoorTerritoryModel or _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.HouseTerritoryModel then
            table.insert(ItemTypes,self.TabSelectType)

            local PartsCategory = HouseCommon.HouseItemCatagory.Invalid

            if _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.IndoorTerritoryModel then
                PartsCategory = self:RevertPartsCategoryToHouseItemCategory(_G.HousingMgr.SelectInDoorPartsCategory,true)
            else
                PartsCategory = self:RevertPartsCategoryToHouseItemCategory(_G.HousingMgr.SelectHousePartsCategory,false)
            end

            if PartsCategory ~= HouseCommon.HouseItemCatagory.Invalid then
                if self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Bag then
                    --显示背包当前数量
                    self:UpdateBagInfo()

                    if self.PreviewModelData.Bag[PartsCategory] == nil then
                        HouseItems = _G.BagMainVM:GetHouseItems(ItemTypes)
                        self:AddBagPreviewData({Type = PartsCategory,Items = HouseItems})
                    else
                        HouseItems = self.PreviewModelData.Bag[PartsCategory]
                    end
                else
                    --显示仓库当前数量
                    self:UpdateDepotInfo()

                    if _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.IndoorTerritoryModel then
                        if self.PreviewModelData.InternalDepot[PartsCategory] == nil then
                            HouseItems = _G.HousingMgr:GetDepotItems(ItemTypes)
                            self:AddDepotPreviewData({Type = PartsCategory,Items = HouseItems})
                        else
                            HouseItems = self.PreviewModelData.InternalDepot[PartsCategory]
                        end
                    else
                        if self.PreviewModelData.HouseDepot[PartsCategory] == nil then
                            HouseItems = _G.HousingMgr:GetDepotItems(ItemTypes)
                            self:AddDepotPreviewData({Type = PartsCategory,Items = HouseItems})
                        else
                            HouseItems = self.PreviewModelData.HouseDepot[PartsCategory]
                        end
                    end
                end
            end
        else
            if self.TabSelectType == 100 or self.TabSelectType == 101 or self.TabSelectType == 102 then --全部
                local Children = self.TabList[1].Children
                for k,v in ipairs(Children) do
                    if v.Key ~= 100 and v.Key ~= 101 and v.Key ~= 102 then
                        table.insert(ItemTypes,v.Key)
                    end
                end
            else
                table.insert(ItemTypes,self.TabSelectType)
            end

            if self.TabSelectIndex == HouseCommon.SelectHouseLeftBarType.Bag then
                --显示背包当前数量
                self:UpdateBagInfo()
                HouseItems = _G.BagMainVM:GetHouseItems(ItemTypes)
            else
                self:UpdateDepotInfo()
                HouseItems = _G.HousingMgr:GetDepotItems(ItemTypes)
            end
        end

        --一体墙现在没有
        if self.TabSelectType == HouseCommon.HouseItemTabCatagory.EXTERIOR_ALLWALL_Bag or self.TabSelectType == HouseCommon.HouseItemTabCatagory.EXTERIOR_ALLWALL_Depot then
            HouseItems = {}
        end

        local RefreshData = {}

        for k,Item in pairs(HouseItems) do
            Item.Index = #RefreshData + 1

            if Item.GID == SelectGID then
                Item.Selected = true
            end

            RefreshData[#RefreshData + 1] = Item
        end

        if #RefreshData > 0 then
            self.CommBackpackEmptyVisible = false
            self.CommBackpackEmptySVisible = false
            self.CurrentItemVMList.UpdateVMParams = {IsAllowDoubleClick = true}
            self.CurrentItemVMList:UpdateByValues(RefreshData)

            --这里要判断如果不符合房子大小的，则对图标做灰化
            if _G.HousingMgr:GetHouseModel() == HouseCommon.HouseModel.HouseTerritoryModel then

            end

        else
            if _G.HousingMgr:GetRightBarExpend() then
                self.CommBackpackEmptyVisible = true
                self.CommBackpackEmptySVisible = false
            else
                self.CommBackpackEmptyVisible = false
                self.CommBackpackEmptySVisible = true
            end
        end
    end
end

function HouseMainPanelVM:GetTabSelectIndex()
    return self.TabSelectIndex
end

---@type 切换标签
---@param Index number @一级标签索引
---@param SubIndex number @二级页签索引
function HouseMainPanelVM:ChangeTab(InHouseModel, ParentKey, ChildKey)
    --重复点相同的地方无效
    if self.LastHouseModel == InHouseModel and ParentKey == self.TabSelectIndex and ChildKey == self.TabSelectType then
        return
    end

    self.LastHouseModel = InHouseModel
    self.TabSelectIndex = ParentKey
    self.TabSelectType = ChildKey

    --设置选择的内装类型
    if ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_WALL_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_WALL_Depot then
        _G.HousingMgr:SetSelectInDoorPartsCategory(HouseCommon.HouseInteriorParts.INTERIOR_CATEGORY_WALL)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_FLOOR_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_FLOOR_Depot then
        _G.HousingMgr:SetSelectInDoorPartsCategory(HouseCommon.HouseInteriorParts.INTERIOR_CATEGORY_FLOOR)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_LIGHT_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.INTERIOR_LIGHT_Depot then
        _G.HousingMgr:SetSelectInDoorPartsCategory(HouseCommon.HouseInteriorParts.INTERIOR_CATEGORY_ILLUMINATION)
    end

    --设置选择的外装类型
    if ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WALL_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WALL_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_WALL)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_ROOF_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_ROOF_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_ROOF)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WINDOW_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WINDOW_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_WIND)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_DOOR_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_DOOR_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_DOOR)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WALL_OPTION_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_WALL_OPTION_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_OPT_WALL)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_ROOF_OPTION_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_ROOF_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_OPT_ROOF)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_SIGN_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_SIGN_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_OPT_SIGN)
    elseif ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_FENCE_Bag or ChildKey == HouseCommon.HouseItemTabCatagory.EXTERIOR_FENCE_Depot then
        _G.HousingMgr:SetSelectHousePartsCategory(HouseCommon.HouseExteriorParts.HOUSE_EXTERIOR_PARTS_FENCE)
    end

    if _G.HousingMgr:GetRightBarExpend() then
        self.CommBackpackEmptyVisible = true
        self.CommBackpackEmptySVisible = false
    else
        self.CommBackpackEmptyVisible = false
        self.CommBackpackEmptySVisible = true
    end

    self:UpdateItemList()
end

function HouseMainPanelVM:SetEmptyItem(IsEmpty)
    self.ItemDetailVisible = not IsEmpty
end

function HouseMainPanelVM:GetItem(Index)
    local ItemVM = self.CurrentItemVMList:Get(Index)
    if ItemVM and ItemVM.IsValid == true and ItemVM.Item then
        return ItemVM.Item
    end

    return nil
end

--设置当前选择的道具
function HouseMainPanelVM:SetCurItem(Index)
    self.CurGID = nil
    local CurItemVM = self.CurrentItemVMList:Get(self.ItemIndex)
    if CurItemVM and CurItemVM.IsValid == true and CurItemVM.Item then
        CurItemVM:SetItemSelected(false)
    end

    local ClickedItemVM = self.CurrentItemVMList:Get(Index)
    self:SetEmptyItem(ClickedItemVM == nil or ClickedItemVM.IsValid == false)
    if ClickedItemVM and ClickedItemVM.IsValid == true and ClickedItemVM.Item then
        ClickedItemVM:SetItemSelected(true)
        self.CurGID = ClickedItemVM.Item.GID
    end

    self.ItemIndex = Index
end

function HouseMainPanelVM:GetCurItem()
    local CurItemVM = self.CurrentItemVMList:Get(self.ItemIndex)
    if CurItemVM and CurItemVM.IsValid == true and CurItemVM.Item and CurItemVM.Item.GID == self.CurGID then
        CurItemVM.Item.FreezeGroup = CurItemVM.FreezeGroup
        return CurItemVM.Item
    end

    self.ItemIndex = self:UpdateItemIndexByGID(self.CurGID)

    local CurItemVM = self.CurrentItemVMList:Get(self.ItemIndex)
    if CurItemVM and CurItemVM.IsValid == true and CurItemVM.Item then
        return CurItemVM.Item
    end

    return nil
end

function HouseMainPanelVM:UpdateItemIndexByGID(GID)
    if GID == nil then
        return
    end

    for i = 1, self.CurrentItemVMList:Length() do
        local ItemVM = self.CurrentItemVMList:Get(i)
        if ItemVM and ItemVM.IsValid == true and ItemVM.Item and ItemVM.Item.GID == GID then
            return i
        end
    end
end

--更新背包信息
function HouseMainPanelVM:UpdateBagInfo()
    local Capacity = BagMgr.Capacity
    local BagCount = BagMgr:CalcBagUseCapacity()
    local CapacityText = string.format("%d/%d", BagCount, Capacity)
    self.RichTextBoxWarehouseText = RichTextUtil.GetText(string.format("%s:%s",LSTR(1640012),CapacityText), "ffffff", 0, nil)
end

function HouseMainPanelVM:UpdateDepotInfo()
    local Depot = _G.HousingMgr:GetCurrentDepot()
    local HouseRegionCfg = _G.HousingMgr:GetHouseRegionCfg()

    if HouseRegionCfg ~= nil then
        if Depot ~= nil then
            self.RichTextBoxWarehouseText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640010),#Depot.ItemList,HouseRegionCfg.DepotSize), "ffffff", 0, nil)
        else
            self.RichTextBoxWarehouseText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640010),0,HouseRegionCfg.DepotSize), "ffffff", 0, nil)
        end
    else
        if Depot ~= nil then
            self.RichTextBoxWarehouseText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640010),#Depot.ItemList,0), "ffffff", 0, nil)
        else
            self.RichTextBoxWarehouseText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640010),0,0), "ffffff", 0, nil)
        end
    end
end

function HouseMainPanelVM:UpdatePlacedInfo()
    local HouseRegionCfg = _G.HousingMgr:GetHouseRegionCfg()
    local FurnitureList = _G.HousingMgr:GetFurnitureList(_G.HousingMgr.HouseID,_G.HousingMgr.Region)

    if FurnitureList ~= nil then
        if HouseRegionCfg ~= nil then
            self.RichTextBoxlayoutText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640001),#FurnitureList.Entities,HouseRegionCfg.FurnitureLimit), "ffffff", 0, nil)
        else
            self.RichTextBoxlayoutText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640001),#FurnitureList.Entities,0), "ffffff", 0, nil)
        end
    else
        if HouseRegionCfg ~= nil then
            self.RichTextBoxlayoutText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640001),0,HouseRegionCfg.FurnitureLimit), "ffffff", 0, nil)
        else
            self.RichTextBoxlayoutText = RichTextUtil.GetText(string.format("%s:%d/%d",LSTR(1640001),0,0), "ffffff", 0, nil)
        end
    end
end

